shell_head('Panel Petugas','admin',['libs'=>['chart','leaflet'],'h1'=>'Panel Petugas','sub'=>'Kelola laporan masyarakat, penugasan, dan status penanganan.']);?><div><div><p class="text-muted">Selamat datang, <?=e($u['name'])?>.</p>
